/* Execute a pure GLSL probe with two independent colour banks. Inputs are
 * generated by the shader, and the last bank is read back without replaying
 * captured draw calls. This is a driver/unit probe, not a Minecraft benchmark.
 */
#include <OpenGL/OpenGL.h>
#include <OpenGL/gl3.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static void fail(const char *message) {
    fprintf(stderr, "%s\n", message);
    exit(1);
}

static char *readSource(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) fail("Cannot open GLSL probe");
    fseek(file, 0, SEEK_END);
    long bytes = ftell(file);
    rewind(file);
    char *source = calloc((size_t)bytes + 1, 1);
    if (!source || fread(source, 1, (size_t)bytes, file) != (size_t)bytes) {
        fail("Cannot read GLSL probe");
    }
    fclose(file);
    return source;
}

static GLuint compile(GLenum stage, const char *source) {
    GLuint object = glCreateShader(stage);
    glShaderSource(object, 1, &source, NULL);
    glCompileShader(object);
    GLint valid;
    glGetShaderiv(object, GL_COMPILE_STATUS, &valid);
    if (!valid) {
        char log[8192];
        glGetShaderInfoLog(object, sizeof(log), NULL, log);
        fail(log);
    }
    return object;
}

int main(int argc, char **argv) {
    if (argc != 7) fail("world-probe fragment width height frames format output");
    int width = atoi(argv[2]);
    int height = atoi(argv[3]);
    int frames = atoi(argv[4]);
    if (width < 1 || height < 1 || frames < 1) fail("Invalid probe dimensions");
    CGLPixelFormatAttribute attributes[] = {kCGLPFAOpenGLProfile,
        (CGLPixelFormatAttribute)kCGLOGLPVersion_3_2_Core, kCGLPFAAccelerated, 0};
    CGLPixelFormatObj format;
    CGLContextObj context;
    GLint formats;
    if (CGLChoosePixelFormat(attributes, &format, &formats) != kCGLNoError || !format) {
        fail("No accelerated OpenGL context");
    }
    if (CGLCreateContext(format, NULL, &context) != kCGLNoError) fail("Cannot create context");
    CGLDestroyPixelFormat(format);
    CGLSetCurrentContext(context);
    GLuint array, framebuffer, textures[2];
    glGenVertexArrays(1, &array);
    glBindVertexArray(array);
    glGenFramebuffers(1, &framebuffer);
    glBindFramebuffer(GL_FRAMEBUFFER, framebuffer);
    glGenTextures(2, textures);
    GLenum storage = strcmp(argv[5], "RGBA16F") == 0 ? GL_RGBA16F : GL_RGBA32F;
    for (int bank = 0; bank < 2; bank++) {
        glBindTexture(GL_TEXTURE_2D, textures[bank]);
        glTexImage2D(GL_TEXTURE_2D, 0, storage, width, height, 0, GL_RGBA, GL_FLOAT, NULL);
        glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_NEAREST);
        glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_NEAREST);
        glFramebufferTexture2D(GL_FRAMEBUFFER, GL_COLOR_ATTACHMENT0, GL_TEXTURE_2D, textures[bank], 0);
        glDrawBuffer(GL_COLOR_ATTACHMENT0);
        if (glCheckFramebufferStatus(GL_FRAMEBUFFER) != GL_FRAMEBUFFER_COMPLETE) fail("Probe FBO incomplete");
        glClearColor(0, 0, 0, 0);
        glClear(GL_COLOR_BUFFER_BIT);
    }
    const char *vertex = "#version 330 core\nvoid main(){gl_Position=vec4(gl_VertexID==1?3:-1,gl_VertexID==2?3:-1,0,1);}";
    char *fragment = readSource(argv[1]);
    GLuint program = glCreateProgram();
    glAttachShader(program, compile(GL_VERTEX_SHADER, vertex));
    glAttachShader(program, compile(GL_FRAGMENT_SHADER, fragment));
    free(fragment);
    glLinkProgram(program);
    GLint valid;
    glGetProgramiv(program, GL_LINK_STATUS, &valid);
    if (!valid) {
        char log[8192];
        glGetProgramInfoLog(program, sizeof(log), NULL, log);
        fail(log);
    }
    glUseProgram(program);
    glUniform1i(glGetUniformLocation(program, "previous"), 0);
    glViewport(0, 0, width, height);
    for (int frame = 0; frame < frames; frame++) {
        glBindTexture(GL_TEXTURE_2D, textures[frame % 2]);
        glFramebufferTexture2D(GL_FRAMEBUFFER, GL_COLOR_ATTACHMENT0, GL_TEXTURE_2D, textures[1 - frame % 2], 0);
        glUniform1i(glGetUniformLocation(program, "probeFrame"), frame);
        glDrawArrays(GL_TRIANGLES, 0, 3);
    }
    size_t components = (size_t)width * height * 4;
    float *pixels = calloc(components, sizeof(float));
    if (!pixels) fail("Cannot allocate probe readback");
    glReadBuffer(GL_COLOR_ATTACHMENT0);
    glReadPixels(0, 0, width, height, GL_RGBA, GL_FLOAT, pixels);
    if (glGetError() != GL_NO_ERROR) fail("GLSL probe raised an OpenGL error");
    FILE *output = fopen(argv[6], "wb");
    if (!output || fwrite(pixels, sizeof(float), components, output) != components) fail("Cannot save probe readback");
    fclose(output);
    free(pixels);
    printf("{\"width\":%d,\"height\":%d,\"frames\":%d,\"gpu\":\"%s\"}\n", width, height, frames, glGetString(GL_RENDERER));
    CGLSetCurrentContext(NULL);
    CGLDestroyContext(context);
    return 0;
}
